import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const PaymentGuideMenuButton = () => {
  const { navigate } = useNavigate();

  const onClickPaymentGuide = () => {
    navigate({
      pathname: PATHS.paymentGuide,
      search: '?defaultTabIndex=0',
    });
  };

  return (
    <button type="button" className="menu-btn" onClick={onClickPaymentGuide}>
      <span className="menu-btn-text">{i18n.t('usageGuide')}</span>
    </button>
  );
};
