import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const MyWalletMenuButton = () => {
  const { navigate } = useNavigate();
  return (
    <button
      type="button"
      className={`menu-btn no-icon`}
      onClick={() => {
        navigate(PATHS.myWallet.manageWallet);
      }}
    >
      <span className="menu-btn-text">{i18n.t('manageMyWallet')}</span>
    </button>
  );
};
