import i18n from '~/shared/i18n/i18n';
import { usePhoneCall } from '~/shared/lib/hooks';

export const HelpDesk = () => {
  const { openPhoneCall } = usePhoneCall();

  const handlePhoneCall = (number: string) => () => {
    openPhoneCall(number);
  };

  return (
    <div className="help-area">
      <div className="help-box">
        <div className="help-desk">
          <b>{i18n.t('customerCenter')} : </b>
          <button
            type="button"
            className="help-call"
            onClick={() => {
              handlePhoneCall('02-1111-1111');
            }}
          >
            1111-1111
          </button>
        </div>
        <div className="help-desk">
          <p>{i18n.t('weekdays')} 09:00 ~ 18:00</p>
        </div>
      </div>
    </div>
  );
};
