import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';
import { useCopy } from '~/shared/lib/hooks';
import { overlay } from '~/shared/lib/overlay';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export const ProfileMyAccountButton = () => {
  const { data: userRes } = useGetUserInfoQuery();
  const hasWallet = !!userRes?.tbCstmrMastr?.hasWallet;
  const { copyBankAccount } = useCopy();
  const { bankName } = useComBankInfo(appConfig.BANK_CODE ?? '');

  const showMyAccount = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          title={i18n.t('issuedAccountNumber')}
          message={
            <button type="button" className={`wallet-account ${appConfig.BANK_CODE}`} onClick={copyBankAccount}>
              <p className="text-[#000]">
                {bankName} {userRes?.tbCstmrMastr?.realAcnutNo} [copy]
              </p>
            </button>
          }
        />
      );
    });
  };
  if (hasWallet) {
    return <></>;
  }
  return (
    <button type="button" className="chk-account" onClick={showMyAccount}>
      {i18n.t('viewMyAccountNumber')}
    </button>
  );
};
