import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { Dialog } from '~/shared/ui/dialogs/dialog';
import { TermsDialogContent } from './terms-dialog-content';

export const TermsMenuButton = () => {
  const onClickTerms = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog afterLeave={unmount} open={isOpen} onClose={close} fullScreenMode message={<TermsDialogContent />} />
      );
    });
  };
  return (
    <button type="button" className="menu-btn" onClick={onClickTerms}>
      <span className="menu-btn-text">{i18n.t('termsAndConditions')}</span>
    </button>
  );
};
